import csv, numpy as np
def load(f):
    r=list(csv.reader(open(f))); h=r[0]; return h, np.array([[float(x) for x in row] for row in r[1:]])
h,ref=load('f_nopred_0.csv')
abs_zero = {'scaled_flux_surface_right':1e4,'scaled_flux_surface_left':1e6,'scaled_mobile_deuterium':1e4,'scaled_trapped_deuterium_1':1e9,'scaled_trapped_deuterium_2':1e4}
worst={}
for k in (1,2,3):
    _,a=load(f'f_nopred_{k}.csv')
    for j,c in enumerate(h):
        if c=='time': continue
        z=abs_zero.get(c,1e-10); m=np.abs(ref[:,j])>z
        if not m.any(): continue
        d=(np.abs(a[m,j]-ref[m,j])/np.abs(ref[m,j])).max()
        worst[c]=max(worst.get(c,0),d)
for c,v in sorted(worst.items(), key=lambda x:-x[1])[:8]: print('%-40s max rel spread %.2e'%(c,v))
print('max over all columns: %.2e'%max(worst.values()))
EOF

